\la{prop16}

- [(a)]
For $(n-k,n) \in L_{\epsilon}$, $D^{(\epsilon)}_{n-k,n}=\oplus_{-\infty}^{\infty} E(t)$, where $E(t)$ is

\begin{equation}
\begin{cases}
a^{t}\,\c[h],  &  \mbox{ for } t \geq n-k(k-\epsilon+1)+1  ,\\[0.15cm]
a^{t}\cdot l \big(h-n+(k-\epsilon)(k-1)+t \big)
\, \c[h], &  \mbox{ for }   0 < t  \le   n-k(k-\epsilon+1) ,\\[0.15cm]
\c[h],  &  \mbox{ for } t=0, \\[0.15cm]
b^{-t}\cdot \frac{s_{n,2k} (h+t)} {s_{n,2k}(h)}\cdot
l \big(h-n+(k-\epsilon)(k-1) \big) \, \c[h],  & \mbox{ for }
-n+k(k-\epsilon+1) \le t <0 ,\\[0.2cm]
b^{-t}\cdot \frac{s_{n,2k} (h+t)} {s_{n,2k}(h)} \, \c[h]  , & \mbox{ for }  t < -n+k(k-\epsilon+1).
\end{cases}   \nonumber
\end{equation}

- [(b)] For $(n,n-k)\in L_{\epsilon}$, $D_{n,n-k}^{(\epsilon)}=\oplus_{-\infty}^{\infty}F(t)$,
where $F(t)$ is

\begin{equation}
\begin{cases}
a^{t}\,\c[h],  &  \mbox{ for } t \geq n-k(k+\epsilon)+2 , \\[0.15cm]
a^{t}\cdot l \big(h-n+(k+\epsilon-1)(k-1)+t \big)
\, \c[h], &  \mbox{ for }   0 < t  \le   n-k(k+\epsilon)+1, \\[0.15cm]
\c[h],  &  \mbox{ for } t=0, \\[0.15cm]
b^{-t}\cdot \frac{s_{n,2k} (h+t)} {s_{n,2k}(h)}\cdot
l \big(h-n+(k-\epsilon)(k-1) \big) \, \c[h],  & \mbox{ for }
-n+k(k+\epsilon)-1 \le t <0, \\[0.2cm]
b^{-t}\cdot \frac{s_{n,2k} (h+t)} {s_{n,2k}(h)} \, \c[h]  , & \mbox{ for }  t <-n+k(k+\epsilon)-1 .
\end{cases}   \nonumber
\end{equation}
